mapper.select:
SELECT distinct pf.id AS id, pf.bill_date AS billDate, pf.code, pf.handover_no AS handoverNo, pf.platform_package_no AS platformPackageNo, COALESCE(pf.handover_no,'') || '/' || COALESCE(pf.platform_package_no,'') as platformNo, pf.logistics_supplier_id AS logisticsSupplierId, pf.logistics_supplier_name AS logisticsSupplierName, pf.transport_no AS transportNo, pf.total_package_qty AS totalPackageQty, pf.total_package_weight AS totalPackageWeight, pf.weight_unit AS totalPackageWeightUnit, pf.upload_status AS uploadStatus, pf.print_status AS printStatus, pf.handover_status AS handoverStatus, pf.remark, pf.create_user_name AS createUserName, pf.create_time AS createTime FROM package_forecast pf LEFT JOIN package_forecast_detail pfd ON pf.id = pfd.main_id AND pfd.is_deleted = FALSE WHERE ${params.sqlMap.default} and pf.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pf.create_time DESC

SELECT pf.id AS id, pfd.id AS detailId, pf.bill_date AS billDate, pf.code, pf.handover_no AS handoverNo, pf.platform_package_no AS platformPackageNo, pf.logistics_supplier_id AS logisticsSupplierId, pf.logistics_supplier_name AS logisticsSupplierName, pf.transport_no AS transportNo, pf.total_package_qty AS totalPackageQty, pf.total_package_weight AS totalPackageWeight, pf.weight_unit AS totalPackageWeightUnit, pf.upload_status AS uploadStatus, pf.print_status AS printStatus, pf.handover_status AS handoverStatus, pf.remark, pf.create_user_name AS createUserName, pf.create_time AS createTime, pfd.so_id AS soId, pfd.so_code AS soCode, pfd.logistics_channel_id AS logisticsChannelId, pfd.logistics_channel_name AS logisticsChannelName, pfd.track_no AS trackNo, pfd.transport_no AS minPackageTransportNo, pfd.weight, pfd.weight_unit AS weightUnit, pfd.handover_status AS minPackageHandoverStatus FROM package_forecast pf LEFT JOIN package_forecast_detail pfd ON pf.id = pfd.main_id AND pfd.is_deleted = FALSE WHERE ${params.sqlMap.default} and pf.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pf.create_time DESC
